# ============= W53 (E5a): THE SHOT'S IMPACT SPARK -- POOL E's DATA ===========
#
# `src/spark.js` ports $289F54 (the allocator) and $28A098 (the driver).  Two
# windows, and BOTH ENDS OF BOTH ARE PINNED BY SOMETHING THAT IS NOT A READING:
#
#   $28A5AC..$28AB85, 1,498 B, ONE contiguous block of three things:
#       $28A5AC          template 0                              22 B
#       $28A5C2          THE DESCRIPTOR LIST, 36 longwords       144 B
#                        ($22CA1C..$22CBC0 step $C) -- and $28A5C2 + 144 lands
#                        EXACTLY on $28A652, where template 1 starts
#       $28A652..$28A785 templates 1..14, stride 22              308 B
#                        ...and $28A770 + 22 == $28A786          EXACT
#       $28A786..$28AB85 the 256-entry POINTER TABLE              1,024 B
#                        $289F68 reads it with `move.w $803916,D5 / add.w D5,D5
#                        / add.w D5,D5` -- NO MASK, exactly like $242FDE -- so
#                        it must be 256 entries, and [M] $28A786 + 256*4 ==
#                        $28AB86, which disassembles to `addq.b #1,$803917`,
#                        i.e. CODE.  EXACT, and it is the far end.
#       [M] the 256 entries resolve to 15 DISTINCT templates (one named 32
#       times, fourteen named 16), and all 15 differ ONLY in the starting
#       animation cursor: $8C $80 $74 $68 $5C $50 $44 $38 $2C $20.
#
#   $28ABFA..$28AC39, 64 B, $28ABE0's draw table (`moveq #$3f` masks the index).
#       [M] $28ABFA + 64 == $28AC3A == `lea $81DB90,A0`, code.  EXACT.
#
# W90 EXPORTS THE ONE THING THIS BLOCK USED TO NAME AS DELIBERATELY ABSENT.
# The paragraph here used to read: "NOT EXPORTED, and named rather than skipped:
# $28A506's template and its own 36-longword list at $28A51C
# ($22C6BC..$22C860). They belong to $289F96 / $289FC0 / $289FDA -- the LASER's
# three pool-E producers, which this wave does not port."  W90 ports $289FC0 and
# $289FDA, so the data is exported now and the sentence would otherwise have
# become the eighth comment on this project that stopped being true and stayed.
# $289F96 is still unported -- see the W90 window's `why`.
SHOT_WINDOWS.extend([
    (0x28A2D6, 0x000A, "W90: $28A252's SPEED-BY-POWER table, five words, read "
                       "by $28A2A4 `move.w (A2),D0` at the byte offset the "
                       "player's laser power word ($810408/$81046A) supplies. "
                       "FIVE because that word is `+= 2, refuse at 8`, and the "
                       "far end $28A2E0 is fill dispatch $28A232's ENTRY 1 -- "
                       "`addq.w #$6,A0 / rts`, the null tail. Both pins are "
                       "asserted by beam_impact_speed_indices()"),
    (0x28A506, 0x00A6, "W90: the LASER IMPACT EFFECT's template ($28A506, 22 "
                       "bytes) and its own 36-longword descriptor list "
                       "($28A51C -> $22C6BC..$22C860 step $C). $289FC0/$289FDA "
                       "`lea $28A506(PC),A2` name the template as an "
                       "IMMEDIATE, not through a pointer table, so there is "
                       "one. Both extents are the cartridge's: $28A506 + $16 "
                       "== $28A51C (the template ABUTS the list its own +$10 "
                       "names) and $28A51C + 36*4 == $28A5AC, which is W53's "
                       "template 0 and the base of the window below. THREE "
                       "windows now abut: $28A464..$28A506..$28A5AC..$28AB86. "
                       "$289F96 shares this template and is still unported -- "
                       "it allocates TWO records (`moveq #$1,D1`) and is "
                       "reached from $25485E, the beam's SEGMENT driver"),
    (0x28A5AC, 0x05DA, "W53 POOL E: the 15 spark templates, their shared "
                       "36-entry descriptor list $28A5C2, and the 256-entry "
                       "pointer table $28A786 -- $28A5AC..$28AB85, whose far "
                       "end is $28AB86 (`addq.b #1,$803917`, code)"),
    (0x28ABFA, 0x0040, "W53 POOL E: $28ABE0's 64-byte draw table $28ABFA "
                       "(indexed by $803916 & $3F), read by $28A39E for the "
                       "spark's heading -- far end $28AC3A is code"),
])

# ---------------------------------------------------------------- WAVE 54
# POOL B -- THE ENEMY DEATH EXPLOSION ($289004 / $288E4E, src/effects.js).
#
# ONE WINDOW FOR THE TWO SCRIPT TABLES AND ALL OF THEIR DATA, and the reason is
# the same one the WAVE 45 block gives: the descriptor lists, the duration lists
# and the 8-byte escape commands are interleaved and the lists are walked in
# LOCKSTEP, so naming each by extent would be a schema decision the ROM does not
# support.  Both ENDS are pinned by data that is not this line -- see
# `check_pool_b_extents`, which asserts all of it on every export:
#
#   $221520 + 34*8 == $221630   table A ends where table B begins
#   $221630 + 34*8 == $221740   and $221740 IS entry [0][0]'s descriptor list
#   [M] walking all 68 entries the way $288E4E and $288E20 do, the data runs
#       $221740..$222618 -- so the whole block is $221520..$222617, 4,344 B
#
# AND TWO REMAP ROWS THE DEATH ARMS INDEX, both pinned from the far side:
#   $267FA0  3 rows of 6 words (death / hit / $289AF4), and $267FC4 is `4E75`
#   $278320  the first two of those rows again, and $278338 is $0022C59C,
