# ======= W57 (M1): ENEMY TYPE $1C -- WHAT THE MIDBOSS'S DEATH SPAWNS =========
#
# `$26B7E0 moveq #$1C,D0 / $26B7E2 jsr $263684` is the ONLY enqueuer of type
# $1C in build B (W56 Â§2.2 scanned all 44 absolute-long call sites of the two
# deferred-spawn entries), and the type table's LO entry $267904 is
# (init $26C1C2, handler $26C20C).  Every byte the port reads for it lives in
# ONE window, and BOTH ENDS ARE PINNED BY SOMETHING THAT IS NOT A READING:
#
#   $26C1C2  the 8-byte init STUB `3B7C 0000 0004 / 4E75` -- run length $0000.
#            `initDispatch` reads the immediate at init+2 ($26C1C4), which is
#            the word that threw on the live page before this line existed.
#            The NEAR end is the type table's own init pointer.
#   $26C1CA  the init BODY (init+8).  Five instructions, src/initbody.js.
#   $26C1EE  the RECORD prototype, ONE word ($26C1DC `moveq #$0,D0` -> $26377A
#            copies D0+1 = 1 word).  [M] $0000.
#   $26C1F0  the SUB-RECORD prototype.  [M] its flags word is $8000, bit 15 SET,
#            so $2637A2 takes the LONG form: 28 table bytes for the one
#            sub-record the run length asks for.  $26C1F0 + 28 == $26C20C,
#            which IS the handler -- i.e. the FAR end is code, exactly, with no
#            slack.  That is why the length is $4A and not the $50 the
#            diagnostic proposed: $50 would claim six bytes of $26C20C's
#            `cmpi.w #$105,$8130CE` as data.
#
# NOT EXPORTED, and named rather than skipped: nothing.  The handler's own
# source data -- $227AF8, 23 columns x 36 B of the STAGE-1 BG column stream --
# is already inside the WAVE 13 window $225B78+$22E0 (columns 224..246 of 248;
# $225B78 + 224*36 == $227AF8 exactly, and 23*36 == 828 == 207 longwords ==
# 23 columns x 9 rows, which is what $26C23C's two `dbra`s write).
# ==================== W62 (S1): THE STAGE END, THREE WINDOWS =================
#
# `src/stageend.js` and `src/scheduler.js` read exactly these three, and each is
# read by an INSTRUCTION named on its line.
SHOT_WINDOWS.extend([
    # $241198 `lea ($240F62,PC),A0` / $24119C `move.w ($4,A0,D1.w),D1` -- the
    # object dispatch table's PRIORITY word, which `$241182` reads for every
    # create.  20 entries x 8 bytes.  Entry [6] is ($28D63C, priority $000A),
    # the stage-clear object; entry [1] is ($26127A, $001A), the background.
    # The port has carried both priorities as literals since W13; W62 is the
    # first wave to CREATE an object and it reads the word the cartridge has.
    (0x240F62, 0x00A0, "W62: the object dispatch table $240F62 -- 20 entries of "
                       "(handler.l, priority.w, pad.w), read by $24119C for "
                       "every $241182 create"),
    # $2597F2 `movea.l $812A70,A0 / movea.l (A0,D0.w),A0` -- THE A3 SCRIPT
    # TABLE, installed by `$29272E jsr $259554` with A3 = $29370A.  Ten
    # {init, step} pairs; entry [6] is ($293DC6, $293E04), the boss's DEATH
    # ANIMATION and the only script W62 registers.
    # **W82 WIDENED THIS FROM $50 TO $A8 AND THE OLD EXTENT WAS SHORT** -- the
    # third time this exact defect has been found on this boss's tables (W64 on
    # $294F68, W54 6.2 on the general rule).  W62 declared TEN pairs because ten
    # is the number of SLOTS; the table is indexed by the script ID, which is a
    # byte, and [M] the boss has TWENTY-ONE D-script ids.  Recon 48 2.4
    # enumerated all 21 and the window did not follow.
    # The far end is pinned the same way `$294F68`'s and `$28840E`'s are: [21] is
    # `42 54 4E 75` = `clr.w (a4) / rts`, the shared "script done" tail that
    # recon 48 1.4 already names as the landmark bounding tables D and E.
    # WHAT THE SHORT WINDOW COST: nothing yet, and that is the point.  Ids
    # 10,11,14,15,16,17,20 are all live in the checkpoint ladder, and every one
    # of them would have thrown as a ROM-WINDOW read at $29375A+ instead of as
    # the SCRIPT it is -- naming the table rather than the routine, which is the
    # precise failure the comment on this window says it exists to prevent.
    (0x29370A, 0x00A8, "W62/W82: the stage-1 boss's A3 script table $29370A -- "
                       "TWENTY-ONE {init,step} pairs (W62 said ten, which is the "
                       "SLOT count, not the ID count), read through $812A70 by "
                       "$2597F8. Entry [6] = ($293DC6,$293E04) is D-script 6, the "
                       "death animation that fires $2595E8; entry [7] is "
                       "($2943B0,$2943B0), the body animator, the same longword "
                       "twice. [21] is `clr.w (a4)/rts` -- CODE, and the pin"),
    # $2597BE's A1 walk reads this the same way, and W62 DID NOT DECLARE IT AT
    # ALL.  Fifteen pairs; [15] is the same `clr.w (a4) / rts` pin.  Every one of
    # the boss's 49 bullet sites is behind one of these pointers.
    (0x295856, 0x0078, "W82: the stage-1 boss's A1 script table $295856 -- "
                       "FIFTEEN {init,step} pairs read through $812BD4 by "
                       "$2597B8, undeclared until now. NONE is registered; the "
                       "window makes the throw name the SCRIPT ($295948 etc) and "
                       "not the table. [15] is `clr.w (a4)/rts`, the pin"),
    # $2595B8 `move.l (A2)+,D0 / cmpi.l #$FFFFFFFF` -- the A2 list $259554
    # PRE-FILLS $8129D0 from.  Seven longwords and the terminator; the walk at
    # $259682 dispatches through the copy, so the port must read the ROM list to
    # place the same seven pointers.
    # $25974A `movea.l $812984,A0 / movea.l (A0,D0.w),A0` -- THE A0 MAIN
    # SEQUENCER's table, installed with A0 = $293104.  Nine {init,step} pairs;
    # entry [1] is ($2933C2, $2933C2) -- the SAME longword twice, which is the
    # boss's death drift and the only one W62 registers.  [10] onward decodes as
    # code, so nine is the extent.
    (0x293104, 0x0048, "W62: the stage-1 boss's A0 main-sequencer table "
                       "$293104 -- nine {init,step} pairs read through $812984 "
                       "by $259766. Entry [1] = ($2933C2,$2933C2)"),
    # $2596EE `movea.l $812D38,A0 / movea.l (A0,D0.w),A0` -- the A4 table.  Its
    # scripts are the boss's own and NONE is ported; the window exists so that
    # starting one reaches the SCRIPT throw carrying $2954xx rather than a ROM
    # window throw carrying $294F88, which names the wrong thing.
    # **W64 (B2) WIDENED THIS FROM $28 TO $38 AND THE OLD EXTENT WAS SHORT.**
    # W62 declared FIVE {init,step} pairs.  [M] entries [5] and [6] are
    # ($295616,$295626) and ($295684,$2956F6) -- both perfectly ordinary
    # pointer pairs into the same $295xxx script region as [0]..[4] -- and [7]
    # is $397C00C0, i.e. `move.w #$C0,...`, CODE.  So the table is SEVEN pairs
    # and the far end is pinned by the first longword that is an instruction,
    # the same rule W63 used for $28840E[4].
    #
    # It was found by W64's own bomb: a run that bombs kills the midboss
    # sooner, the boss arrives sooner, and `$2596F4 movea.l (A0,D0.w),A0`
    # asked for [5] at logic frame 9,153, where a run that does not bomb had
    # never got past lf 19,533's `$228658`. A SHORT WINDOW IS NOT CAUGHT AT THE
    # EXPORT -- it is caught by `src/rom.js` on a player's machine (W54 Â§6.2),
    # and this is that lesson arriving for the third time.
    (0x294F68, 0x0038, "W62/W64: the stage-1 boss's A4 script table $294F68 -- "
                       "SEVEN {init,step} pairs (W62 said five; [7] is the "
                       "first longword that decodes as code). NONE is "
                       "registered; the window makes the throw name the "
                       "SCRIPT and not the table"),
    (0x292932, 0x0020, "W62: the stage-1 boss's A2 routine list $292932 -- "
                       "SEVEN longwords then $FFFFFFFF, pre-filled into $8129D0 "
                       "by $2595B8. Every slot's RUN bit stays CLEAR"),
])

# ============ W82: THE A2 OBJECT ROUTINES' SPRITE TABLES, THREE WINDOWS =======
#
# `src/boss.js` registers OBJECT routines 2, 3, 4 and 5 (`$292952`, `$292BFA`,
# `$292E0A`, `$292E3E`) -- the four still armed after the boss dies.  Three of
# them index a table of sprite longwords; each window below is the extent an
# INSTRUCTION can reach, and each far end is pinned by the first byte that is
# CODE, which is the rule this file already applies to `$294F68` and `$28840E`.
SHOT_WINDOWS.extend([
    # $292BFA `lea $292C2A(pc),A2` / $292C00 `move.w $AC(A6),D2 / addq.w #$7,D2
    # / lsl.w #$5,D2 / adda.w D2,A2 / adda.w $AA(A6),A2 / move.l (A2),D2`.
    #
    # FIFTEEN ROWS OF $20, AND BOTH BOUNDS COME OUT OF THE ARITHMETIC:
    #  * the `addq.w #$7` is a BIAS, so row 0 is $AC = -7 and the `lea`'s own
    #    address IS the bottom of the table, not its middle.  `adda.w`
    #    sign-extends, so $AC is SIGNED -- and [M] it really does go negative:
    #    `$29578C moveq #$19,D1` feeds `$242190` a target of $19-$20 = -7 through
    #    the `+$20 / -$20` bias pair at `$295798`/`$2957A8`.  The other writer,
    #    `$2948A6` (D-script 15), targets `$20`, i.e. $AC = 0.
    #  * the top is $AC = +7: row 14 ends at $292C2A+$1E0, and $292E0A is
    #    OBJECT 4's first instruction.  Code pins it exactly.
    # Within a row, `$2943B0`'s cursor `$AA(A6)` takes the SEVEN values
    # 0,4,8,$C,$10,$14,$18 -- the `blt` at $2943E2 wraps AT $1C, so the last
    # longword of each 32-byte row is never read.
    (0x292C2A, 0x01E0, "W82: OBJECT 3's sprite table $292C2A -- FIFTEEN $20 rows "
                       "indexed by ($AC(A6)+7)<<5 with $AC SIGNED in [-7,+7], "
                       "read by $292C0E. Far end pinned by $292E0A, OBJECT 4's "
                       "first instruction"),
    # $292E0A `lea $292E32(pc),A2` / $292E10 `move.l (A2),D2` -- NO INDEX AND NO
    # DISPLACEMENT, so only longword [0] is reachable from this routine.  The
    # other two are declared because they are the table, and named as unreachable
    # so the next reader does not go looking for the selector.  $292E3E, OBJECT
    # 5's first instruction, is the pin.
    (0x292E32, 0x000C, "W82: OBJECT 4's sprite table $292E32 -- three longwords "
                       "of which $292E10 can only ever read [0] (no index "
                       "register, no displacement). Far end pinned by $292E3E"),
    # $292E3E `move.b $C6..$C9(A6),D2 / andi.w #$3E,D2 / add.w D2,D2 / move.l
    # $292ECA(pc,D2.w),D2` -- THIRTY-TWO longwords.  `$3E` masks the low bit off
    # and then doubles, so the reachable offsets are 0,4,..,$7C and the extent is
    # exactly $80.  $292F4A is OBJECT 6's first instruction and pins the far end.
    (0x292ECA, 0x0080, "W82: OBJECT 5's sprite table $292ECA -- 32 longwords "
                       "indexed by (byte & $3E)*2 from $C6..$C9(A6), read four "
                       "times by $292E4A/$292E7A/$292E98/$292EB6. Far end pinned "
                       "by $292F4A, OBJECT 6's first instruction"),
])

SHOT_WINDOWS.append(
    (0x26C1C2, 0x004A, "W57: enemy type $1C -- the init stub $26C1C2 (run "
                       "length at init+2), the init body $26C1CA, its 1-word "
                       "record prototype $26C1EE and its 28-byte sub-record "
                       "prototype $26C1F0, whose far end $26C20C is the "
                       "handler (code). Spawned ONLY by the midboss's death "
                       "$26B7E0/$26B7E2"))

# ================== W61 (I2): THE ITEM, `$27E812` + `$27E99E` ================
#
# `src/items.js` ports the sixth pool family -- the item -- and every one of
# these windows is here because an INSTRUCTION reads inside it, named on the
# line.  `check_item_extents` below asserts the geometry these rest on, on every
# export, out of the image rather than out of a comment.
SHOT_WINDOWS.extend([
    # `$23EB06` is the REGISTER-convention enqueue every item body and both
    # collected-animation steppers end with, and `src/spritequeue.js
    # resolveEmitStub` READS ITS CODE to learn the bucket and the convention
    # rather than trusting a number.  It is W36's fifth prologue shape
    # (`addi.w #$C,<ctr>` BEFORE `move.l D1,D0`), so the resolver needs 22 bytes.
    (0x23EB00, 0x0020, "W61: the emitter stub $23EB06 (bucket 17), read by "
                       "spritequeue.js resolveEmitStub"),
    # `$242B3C`'s canned table.  There is NO MASK -- `move.w $803916,D0` then
    # `move.b (A0,D0.w),D0` -- so the index is the whole word and the table is
    # 256 bytes, exactly like $242FDE's.  The far end is pinned by $242CAC,
    # which is the RNG family's NEXT `addq.b #1,$803917` site (src/rng.js's own
    # 32-site scan).  Drawn by both item bounce arms and by BOTH collect tails.
    (0x242BAC, 0x0100, "W61: $242B3C's 256-byte table $242BAC..$242CAB, far end "
                       "pinned by $242CAC (the next addq.b site)"),
    # The kind dispatch, the `rts` entry [7] points at, and kind $0's own
    # four-frame sprite table -- $27E9F8 + $32 == $27EA2A, the first body.
    (0x27E9F8, 0x0032, "W61: $27E9F8 the 8-entry kind dispatch, the $27EA18 "
                       "`rts` entry [7] IS, and kind $0's sprite table $27EA1A"),
    (0x27EBCC, 0x0010, "W61: kind $04 (FULL POWER) sprite table, $27EC64 lea"),
    (0x27ED7C, 0x0010, "W61: kind $08 (the SET ITEM) sprite table, $27EE14 lea"),
    (0x27EF10, 0x0040, "W61: kinds $0C/$14's 16-frame sprite table, $27EF00 lea. "
                       "Those kinds are REFUSED (src/items.js THE REFUSAL) so "
                       "nothing reads this yet; exported with the other four so "
                       "the FIVE tables are enumerated in one place"),
    (0x27F196, 0x0010, "W61: kind $10 (the $8130BE counter) sprite table"),
    # The five collected-animation lists, $27F300..$27F54B.  Each carries an
    # 8-byte header $27F5F4 consumes before indexing; the far end is $27F54C,
    # THE COLLECT TAIL ITSELF ($27F508 + 8 + 17*4).
    (0x27F300, 0x024C, "W61: the five collected-animation lists $27F300/$380/"
                       "$400/$480 (30 entries each) and $27F500 (17), walked by "
                       "$27F5F4/$27F656 -- far end IS $27F54C, the collect tail"),
    # The template table and its six 26-byte templates.  $27F746 + 8*4 ==
    # $27F766 == template [0], and six 26-byte templates land on $27F7E8, CODE.
    (0x27F746, 0x00A2, "W61: $27F746, the 8-entry template pointer table, and "
                       "the SIX 26-byte templates $27F766..$27F7E7 that $27F6AE "
                       "copies into a record's +$06..+$1F"),
])

# ============ W63 (B1): OBJECT TYPE 0, `$28D520` / `$28444E` =================
#
# THREE tables, and every extent is pinned by an INSTRUCTION or by the table
# that abuts it -- never by "what a run reached".
#
#   $287E8E  `$285F52`'s HUD animation cursor.  `$285F64 move.w $81B59A,D0 /
#            lea $287E8E,A0 / move.l (A0,D0.w),$81B59C`, and the index steps
#            `subq.w #$4` and WRAPS TO $38 on borrow (`$285F80 move.w #$38`).
#            $38 = byte offset 56 = entry [14], so FIFTEEN longwords, 60 bytes
#            -- and `$287E8E + $3C == $287ECA`, the next table, confirms it from
#            the other side.
#   $287ECA  `$285F8A`'s.  `moveq #$3F,D0 / and.w $80390A,D0 / add.w D0,D0 /
#            add.w D0,D0` -- the index space IS $00..$FC, so SIXTY-FOUR
#            longwords, 256 bytes, and there is nothing to guess.
#   $28840E  `$286FDA`'s EXTEND-INTERVAL table.  `move.w (A4),D0 / lea
#            $28840E,A5 / move.l (A5,D0.w),D1`, and `$286FFE move.w #$C,(A4)`
#            names the LAST index.  Entry [3] is $FFFFFFFF (the "no more
#            extends" terminator) and entry [4] disassembles as
#            `lea $803824,A0` -- CODE.  FOUR longwords, and the first-threshold
#            table `$2883FE` that `$286FA6` indexes by the same DIP abuts it
#            ($2883FE + $10 == $28840E), which pins it from below as well.
#
# `check_hud_extents` asserts all three out of the image on every export.
SHOT_WINDOWS.extend([
    (0x287E8E, 0x013C, "W63: $287E8E (15 longwords, $285F52's cursor, far end "
                       "pinned by $287ECA) and $287ECA (64 longwords, $285F8A's "
                       "cursor, index space $00..$FC from `and.w #$3F` doubled "
                       "twice)"),
    (0x28840E, 0x0010, "W63: $28840E, $286FDA's FOUR extend-interval longwords "
                       "-- [3] is $FFFFFFFF and [4] is code (`lea $803824,A0`); "
                       "$2883FE + $10 == $28840E pins the near end"),
])

# ===== W113: THE HUD SPRITE-FRAME TABLES (Wave A of the HUD port) ============
#
# THREE windows, every extent pinned by an instruction or by the next table.
