    #     293F64  2050        movea.l (A0),A0       the TABLE ENTRY is an address
    #     293F66  4E90        jsr (A0)              ...and it is CALLED
    #     293F68  586C 0014   addq.w #4,($14,A4)
    #     293F6C  026C 001F 0014  andi.w #$1F,($14,A4)   -> EIGHT entries, wrapped
